                           int nmu,
                           struct lensing * ple
                           );

  int lensing_lensed_cl_ee_bb(
                              double *ksip,
                              double *ksim,
                              double **d22,
                              double **d2m2,
                              double *w8,
                              int nmu,
                              struct lensing * ple
                              );
  int lensing_addback_cl_tt(
                            struct lensing *ple,
                            double *cl_tt
                            );

  int lensing_addback_cl_te(
